      </button>
      <div class="volume-slider-container">
        <input
          type="range"
          min="0"
          max="1"
          step="0.1"
          :value="volume"
          @input="handleVolumeChange"
          class="volume-input"
        />
      </div>
    </div>

    <div class="player-extras">
      <button 
        v-if="currentSong"
        @click="toggleFavorite" 
        class="extra-btn favorite-btn" 
        :class="{ 'is-favorite': isFavorited }"
        :title="isFavorited ? '取消喜欢' : '喜欢'"
      >
        {{ isFavorited ? '❤️' : '🤍' }}
