    <!-- 加入歌单对话框 -->
    <AddToPlaylistDialog
      :visible="showAddDialog"
      :song="songToAdd"
      @update:visible="showAddDialog = $event"
      @success="handleAddDialogClose"
      @cancel="handleAddDialogClose"
    />

    <!-- 播放列表弹窗 -->
    <div v-if="showPlaylist" class="playlist-modal" @click.self="closePlaylist">
      <div class="playlist-content" ref="playlistContent" tabindex="-1" @blur="handleBlur">
        <div class="playlist-header">
          <h3>播放列表 ({{ playlist.length }})</h3>
          <div class="header-controls">
            <button @click="clearPlaylist" class="clear-btn">清空</button>
            <div class="play-mode-selector">
              <button 
                @click="changePlayMode" 
                class="mode-btn"
                :title="playModeText"
              >
                <PlayModeIcon :mode="playMode" />
              </button>
            </div>
          </div>
        </div>
        <div class="playlist-items">
          <div
            v-for="(song, index) in playlist"
            :key="song.id + '-' + index"
            :class="['playlist-item', { active: index === currentIndex }]"
            draggable="true"
            @dragstart="handleDragStart(index, $event)"
            @dragover.prevent="handleDragOver(index, $event)"
            @drop="handleDrop(index, $event)"
            @dragend="handleDragEnd"
            @click="playSongAtIndex(index)"
          >
            <span class="song-index">{{ index + 1 }}</span>
            <div class="song-cover-tiny">
              <img v-if="song.cover" :src="song.cover" :alt="song.name" />
              <span v-else>🎵</span>
            </div>
            <div class="song-info-item">
              <div class="song-name-item">{{ song.name }}</div>
              <div class="song-artist-item">{{ song.artist }}</div>
            </div>
            <div class="song-actions">
              <button @click.stop="toggleActions(index)" class="more-btn">⋮</button>
              <div v-if="activeActionIndex === index" class="action-menu">
                <button @click.stop="removeSong(index)" class="action-item">
                  <span>
                    <svg t="1765371914596" class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="1047" width="20" height="20"><path d="M617.931034 70.62069a70.62069 70.62069 0 0 1 70.62069 70.620689v52.965518h264.827586v176.551724h-58.844689l-50.776276 456.968827A141.241379 141.241379 0 0 1 703.382069 953.37931H320.617931a141.241379 141.241379 0 0 1-140.358621-125.651862L129.447724 370.758621H70.62069V194.206897h264.827586V141.241379a70.62069 70.62069 0 0 1 70.62069-70.620689h211.862068z m223.302621 300.137931H182.74869l50.140689 451.124965a88.275862 88.275862 0 0 0 83.791449 78.441931l3.937103 0.088276h382.764138a88.275862 88.275862 0 0 0 87.746207-78.530207L841.216 370.758621zM388.413793 459.034483v353.103448h-52.965517V459.034483h52.965517z m264.827586 0v353.103448h-52.965517V459.034483h52.965517z m247.172414-211.862069H123.586207v70.620689h776.827586v-70.620689zM617.931034 123.586207H406.068966a17.655172 17.655172 0 0 0-17.655173 17.655172v52.965518h247.172414V141.241379a17.655172 17.655172 0 0 0-15.589517-17.531586L617.931034 123.586207z" p-id="1048"></path></svg>
                  </span> 移除
                </button>
                <button 
                  @click.stop="moveSongUp(index)" 
                  class="action-item"
                  :disabled="index === 0"
                >
                  <span>
                    <svg t="1765372023688" class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="1712" width="20" height="20"><path d="M485.056 350.890667a42.666667 42.666667 0 0 1 57.109333 2.944l256 256a42.666667 42.666667 0 1 1-60.330666 60.330666L512 444.330667 286.165333 670.165333a42.666667 42.666667 0 1 1-60.330666-60.330666l256-256 3.221333-2.944z" fill-opacity=".88" p-id="1713"></path></svg>
                  </span> 上移
                </button>
                <button 
                  @click.stop="moveSongDown(index)" 
                  class="action-item"
                  :disabled="index === playlist.length - 1"
                >
                  <span>
                    <svg t="1765372055933" class="icon" viewBox="0 0 1024 1024" version="1.1" xmlns="http://www.w3.org/2000/svg" p-id="1881" width="20" height="20"><path d="M737.834667 353.834667a42.666667 42.666667 0 1 1 60.330666 60.330666l-256 256a42.666667 42.666667 0 0 1-60.330666 0l-256-256a42.666667 42.666667 0 1 1 60.330666-60.330666L512 579.669333l225.834667-225.834666z" fill-opacity=".88" p-id="1882"></path></svg>
                  </span> 下移
                </button>
              </div>
            </div>
          </div>
          <div v-if="playlist.length === 0" class="empty-playlist">
            播放列表为空
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, onMounted, watch, ref, nextTick } from 'vue'
import { useRouter } from 'vue-router'
import { usePlayerStore } from '../stores/player'
import { usePlaylistStore } from '../stores/playlist'
import { getSongDetail } from '../api/music'
import audioPlayer from '../services/audioPlayer'
import AddToPlaylistDialog from './AddToPlaylistDialog.vue'
import PlayModeIcon from './PlayModeIcon.vue'

const router = useRouter()
const playerStore = usePlayerStore()
const playlistStore = usePlaylistStore()

const songCover = ref('')
const showPlaylist = ref(false)
const playlistContent = ref(null)
const activeActionIndex = ref(null)
const draggedIndex = ref(null)
const playMode = ref('order') // 'order' | 'random' | 'loop'
const showAddDialog = ref(false)
const songToAdd = ref(null)
const songNameRef = ref(null)
const songArtistRef = ref(null)
const showMoreMenu = ref(false)

const currentSong = computed(() => playerStore.currentSong)
const isPlaying = computed(() => playerStore.isPlaying)
const currentTime = computed(() => playerStore.currentTime)
const duration = computed(() => playerStore.duration)
const volume = computed(() => playerStore.volume)
const playlist = computed(() => playerStore.playlist)
const currentIndex = computed(() => playerStore.currentIndex)

// 喜欢状态
const isFavorited = computed(() => {
  if (!currentSong.value || !currentSong.value.id) return false
  return playlistStore.isFavorite(currentSong.value.id)
})



const playModeText = computed(() => {
  switch (playMode.value) {
    case 'random': return '随机播放'
    case 'loop': return '循环播放'
    default: return '顺序播放'
  }
})

const progressPercent = computed(() => {
  return duration.value > 0 ? (currentTime.value / duration.value) * 100 : 0
})

onMounted(() => {
  audioPlayer.setPlayerStore(playerStore)
  // 初始化音量
  audioPlayer.setVolume(playerStore.volume)
  // 设置播放模式获取函数
  audioPlayer.getPlayMode = () => playMode.value
  
  // 检查文本溢出
  checkTextOverflow()
  
  // 恢复播放状态：如果有播放列表和当前歌曲
  if (playerStore.playlist.length > 0 && playerStore.currentSong) {
    const savedTime = playerStore.currentTime
    const currentSongData = playerStore.currentSong
    
    // 恢复封面
    if (currentSongData.cover) {
      songCover.value = currentSongData.cover
    } else if (currentSongData.id) {
      // 如果没有封面，异步获取
      getSongDetail(currentSongData.id).then(res => {
        if (res.data.songs && res.data.songs[0]) {
          const song = res.data.songs[0]
          if (song.al && song.al.picUrl) {
            songCover.value = song.al.picUrl
            currentSongData.cover = song.al.picUrl
          }
        }
      }).catch(err => {
        console.error('获取封面失败:', err)
      })
    }
    
    // 设置为暂停状态（默认不自动播放）
    playerStore.isPlaying = false
    
    // 预加载当前歌曲（但不播放）
    // 直接加载音频源，不调用 playCurrentSong()
    const song = currentSongData
    const songId = song.id
    
    // 获取播放 URL
    playerStore.getSongPlayUrl(song).then(async (playUrlInfo) => {
      let url = playUrlInfo.url
      const isLocal = playUrlInfo.isLocal
      
      // 如果没有本地文件，获取在线 URL
      if (!isLocal) {
        const { getMusicUrl } = await import('../api/music')
        url = await getMusicUrl(songId)
      }
      
      if (url) {
        // 只设置音频源，不播放
        audioPlayer.audio.src = url
        audioPlayer.currentSongId = songId
        playerStore.isLocalPlayback = isLocal
        
        // 恢复播放进度
        if (savedTime > 0) {
          audioPlayer.audio.addEventListener('loadedmetadata', () => {
            audioPlayer.setCurrentTime(savedTime)
          }, { once: true })
        }
        
        // 确保是暂停状态
        audioPlayer.audio.pause()
        playerStore.isPlaying = false
      }
    }).catch(err => {
      console.error('加载歌曲失败:', err)
    })
  }

  // 监听桌面歌词窗口的控制命令
  window.electron.onDesktopLyricControl((action) => {
    switch (action) {
      case 'togglePlay':
        togglePlay()
        break
      case 'prev':
        prev()
        break
      case 'next':
        next()
        break
    }
  })

  // 点击外部关闭更多菜单
  document.addEventListener('click', (e) => {
    const moreMenuContainer = document.querySelector('.more-menu-container')
    if (moreMenuContainer && !moreMenuContainer.contains(e.target)) {
      showMoreMenu.value = false
    }
  })
})

// 检查文本是否溢出
const checkTextOverflow = () => {
  nextTick(() => {
    if (songNameRef.value) {
      const container = songNameRef.value
      const text = container.querySelector('.song-name-text')
      if (text && text.scrollWidth > container.clientWidth) {
        container.classList.add('overflow')
      } else {
        container.classList.remove('overflow')
      }
    }
    
    if (songArtistRef.value) {
      const container = songArtistRef.value
      const text = container.querySelector('.song-artist-text')
      if (text && text.scrollWidth > container.clientWidth) {
        container.classList.add('overflow')
      } else {
        container.classList.remove('overflow')
      }
    }
  })
}

// 监听播放状态变化（仅控制暂停/继续，不触发新歌曲加载）
watch(isPlaying, (newVal) => {
  // 只有在已经有音频源的情况下才控制播放/暂停
  if (audioPlayer.audio.src) {
    if (newVal) {
      audioPlayer.audio.play()
    } else {
      audioPlayer.audio.pause()
    }
  }
  // 同步播放状态到桌面歌词
  syncToDesktopLyric()
})

// 监听当前歌曲变化
watch(currentSong, async (newSong, oldSong) => {
  // 只有在歌曲真正改变时才触发播放
  if (newSong && newSong.id && newSong.id !== oldSong?.id) {
    audioPlayer.playCurrentSong()
    
    // 检查文本溢出
    checkTextOverflow()
    
    // 立即更新封面（如果有的话），避免显示上一首歌的封面
    songCover.value = newSong.cover || ''
    
    // 同步到桌面歌词
    syncToDesktopLyric()
    loadAndSyncLyric(newSong.id)
    
    // 获取歌曲详情以获取图片
    if (!fetchedCovers.has(newSong.id)) {
      fetchedCovers.add(newSong.id)
      try {
        const res = await getSongDetail(newSong.id)
        if (res.data.songs && res.data.songs[0]) {
          const song = res.data.songs[0]
          if (song.al && song.al.picUrl) {
            songCover.value = song.al.picUrl
            // 更新播放列表中的封面
            if (!newSong.cover) {
              newSong.cover = song.al.picUrl
            }
          }
        }
      } catch (error) {
        console.error('获取歌曲详情失败:', error)
      }
    } else if (newSong.cover) {
      // 如果已经请求过且有封面，直接使用
      songCover.value = newSong.cover
    }
  }
})

// 监听播放列表变化，为没有封面的歌曲获取封面
// 使用 Set 记录已经请求过的歌曲，避免重复请求
const fetchedCovers = new Set()

watch(playlist, async (newPlaylist, oldPlaylist) => {
  // 只处理新增的歌曲
  const oldIds = new Set(oldPlaylist?.map(s => s.id) || [])
  const newSongs = newPlaylist.filter(song => !oldIds.has(song.id))
  
  for (const song of newSongs) {
    if (song.id && !song.cover && !fetchedCovers.has(song.id)) {
      fetchedCovers.add(song.id)
      try {
        const res = await getSongDetail(song.id)
        if (res.data.songs && res.data.songs[0]) {
          const songDetail = res.data.songs[0]
          if (songDetail.al && songDetail.al.picUrl) {
            song.cover = songDetail.al.picUrl
          }
        }
      } catch (error) {
        console.error('获取歌曲封面失败:', error)
      }
    }
  }
})

const togglePlay = () => {
  audioPlayer.togglePlay()
}

const next = () => {
  // 只改变索引，让 watch(currentSong) 自动触发播放
  playerStore.next()
}

const prev = () => {
  // 只改变索引，让 watch(currentSong) 自动触发播放
  playerStore.prev()
}

const handleProgressChange = (e) => {
  const time = parseFloat(e.target.value)
  playerStore.setCurrentTime(time)
  audioPlayer.setCurrentTime(time)
}

const handleVolumeChange = (e) => {
  const vol = parseFloat(e.target.value)
  playerStore.setVolume(vol)
  audioPlayer.setVolume(vol)
}

const formatTime = (seconds) => {
  if (!seconds || isNaN(seconds)) return '0:00'
  const mins = Math.floor(seconds / 60)
  const secs = Math.floor(seconds % 60)
  return `${mins}:${secs.toString().padStart(2, '0')}`
}

const togglePlaylist = async () => {
  showPlaylist.value = !showPlaylist.value
  if (showPlaylist.value) {
    // 等待 DOM 更新后自动聚焦
    await nextTick()
    if (playlistContent.value) {
      playlistContent.value.focus()
    }
  }
}

const closePlaylist = () => {
  showPlaylist.value = false
}

const handleBlur = (e) => {
  // 检查失焦的目标是否在播放列表内部
  if (!e.currentTarget.contains(e.relatedTarget)) {
    // 延迟关闭，避免点击内部元素时立即关闭
    setTimeout(() => {
      if (!playlistContent.value?.matches(':focus-within')) {
        showPlaylist.value = false
      }
    }, 100)
  }
}

const playSongAtIndex = (index) => {
  // 只改变索引，让 watch(currentSong) 自动触发播放
  playerStore.currentIndex = index
}

const removeSong = (index) => {
  if (playlist.value.length === 1) {
    playerStore.clearPlaylist()
    audioPlayer.stop()
  } else {
    const wasCurrentSong = index === currentIndex.value
    playerStore.playlist.splice(index, 1)
    
    if (index < currentIndex.value) {
      playerStore.currentIndex--
    } else if (wasCurrentSong) {
      // 删除当前歌曲后，索引不变但歌曲对象会变化
      // 需要强制触发 watch，通过临时改变索引实现
      const tempIndex = playerStore.currentIndex
      playerStore.currentIndex = -1
      nextTick(() => {
        playerStore.currentIndex = Math.min(tempIndex, playlist.value.length - 1)
      })
    }
  }
}

const clearPlaylist = () => {
  if (confirm('确定要清空播放列表吗？')) {
    playerStore.clearPlaylist()
    audioPlayer.stop()
    showPlaylist.value = false
  }
}

const goToSongDetail = () => {
  if (currentSong.value && currentSong.value.id) {
    router.push(`/song/${currentSong.value.id}`)
  }
}

const goToLyrics = () => {
  router.push('/lyrics')
}

const openDesktopLyric = () => {
  window.electron.openDesktopLyric()
  // 打开后立即同步状态
  setTimeout(() => {
    syncToDesktopLyric()
    if (currentSong.value?.id) {
      loadAndSyncLyric(currentSong.value.id)
    }
  }, 500)
}

// 同步播放状态到桌面歌词窗口
const syncToDesktopLyric = () => {
  window.electron.syncPlayerState({
    isPlaying: isPlaying.value,
    songName: currentSong.value?.name || '',
    artistName: currentSong.value?.artist || ''
  })
}

// 监听播放时间变化，同步歌词
watch(currentTime, (time) => {
  if (currentLyrics.value.length === 0) {
    if (currentSong.value?.name && currentLyricText.value !== currentSong.value.name) {
      currentLyricText.value = currentSong.value.name
      window.electron.syncLyric({ lyric: currentSong.value.name })
    }
    return
  }
  
  let lyricText = ''
  for (let i = currentLyrics.value.length - 1; i >= 0; i--) {
    if (time >= currentLyrics.value[i].time) {
      lyricText = currentLyrics.value[i].text
      break
    }
  }
  
  if (lyricText && lyricText !== currentLyricText.value) {
    currentLyricText.value = lyricText
    
    // 找到下一句歌词
    let nextLyricText = ''
    for (let i = 0; i < currentLyrics.value.length; i++) {
      if (time >= currentLyrics.value[i].time) {
        if (i + 1 < currentLyrics.value.length) {
          nextLyricText = currentLyrics.value[i + 1].text
        }
      } else {
        break
      }
    }
    
    window.electron.syncLyric({ lyric: lyricText, nextLyric: nextLyricText })
  }
})

// 歌词相关
const currentLyrics = ref([])
const currentLyricText = ref('')

// 加载并同步歌词
const loadAndSyncLyric = async (songId) => {
  if (!songId) return
  
  try {
    const { getLyric } = await import('../api/music')
    const res = await getLyric(songId)
    if (res.data.lrc && res.data.lrc.lyric) {
      currentLyrics.value = parseLyric(res.data.lrc.lyric)
      if (currentLyrics.value.length > 0) {
        const firstLyric = currentLyrics.value[0].text
        currentLyricText.value = firstLyric
        window.electron.syncLyric({ lyric: firstLyric })
      }
    } else {
      currentLyrics.value = []
      if (currentSong.value?.name) {
        window.electron.syncLyric({ lyric: currentSong.value.name })
      }
    }
  } catch (error) {
    currentLyrics.value = []
  }
}

// 解析歌词
const parseLyric = (lyricText) => {
  if (!lyricText) return []
  
  const lines = lyricText.split('\n')
  const result = []
  
  for (const line of lines) {
    const match = line.match(/\[(\d{2}):(\d{2})\.(\d{2,3})\](.*)/)
    if (match) {
      const minutes = parseInt(match[1])
      const seconds = parseInt(match[2])
      const milliseconds = parseInt(match[3].padEnd(3, '0'))
      const time = minutes * 60 + seconds + milliseconds / 1000
      const text = match[4].trim()
      
      if (text) {
        result.push({ time, text })
      }
    }
  }
  
  return result.sort((a, b) => a.time - b.time)
}

const toggleActions = (index) => {
  activeActionIndex.value = activeActionIndex.value === index ? null : index
}

const moveSongUp = (index) => {
  if (index > 0) {
    const temp = playlist.value[index]
    playlist.value.splice(index, 1)
    playlist.value.splice(index - 1, 0, temp)
    
    // 更新当前播放索引
    if (currentIndex.value === index) {
      playerStore.currentIndex = index - 1
    } else if (currentIndex.value === index - 1) {
      playerStore.currentIndex = index
    }
  }
  activeActionIndex.value = null
}

const moveSongDown = (index) => {
  if (index < playlist.value.length - 1) {
    const temp = playlist.value[index]
    playlist.value.splice(index, 1)
    playlist.value.splice(index + 1, 0, temp)
    
    // 更新当前播放索引
    if (currentIndex.value === index) {
      playerStore.currentIndex = index + 1
    } else if (currentIndex.value === index + 1) {
      playerStore.currentIndex = index
    }
  }
  activeActionIndex.value = null
}

const handleDragStart = (index, event) => {
  draggedIndex.value = index
  event.dataTransfer.effectAllowed = 'move'
  event.target.style.opacity = '0.5'
}

const handleDragOver = (index, event) => {
  event.preventDefault()
  event.dataTransfer.dropEffect = 'move'
}

const handleDrop = (index, event) => {
  event.preventDefault()
  if (draggedIndex.value !== null && draggedIndex.value !== index) {
    const draggedSong = playlist.value[draggedIndex.value]
    const newPlaylist = [...playlist.value]
    
    // 移除拖拽的歌曲
    newPlaylist.splice(draggedIndex.value, 1)
    // 插入到新位置
    newPlaylist.splice(index, 0, draggedSong)
    
    // 更新播放列表
    playerStore.playlist = newPlaylist
    
    // 更新当前播放索引
    if (currentIndex.value === draggedIndex.value) {
      playerStore.currentIndex = index
    } else if (draggedIndex.value < currentIndex.value && index >= currentIndex.value) {
      playerStore.currentIndex = currentIndex.value - 1
    } else if (draggedIndex.value > currentIndex.value && index <= currentIndex.value) {
      playerStore.currentIndex = currentIndex.value + 1
    }
  }
}

const handleDragEnd = (event) => {
  event.target.style.opacity = '1'
  draggedIndex.value = null
}

const changePlayMode = () => {
  const modes = ['order', 'random', 'loop']
  const currentModeIndex = modes.indexOf(playMode.value)
  const newMode = modes[(currentModeIndex + 1) % modes.length]
  
  // 如果切换到随机模式，打乱播放列表
  if (newMode === 'random' && playlist.value.length > 0) {
    const currentSongData = currentSong.value
    const newPlaylist = [...playlist.value]
    
    // Fisher-Yates 洗牌算法
    for (let i = newPlaylist.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [newPlaylist[i], newPlaylist[j]] = [newPlaylist[j], newPlaylist[i]]
    }
    
    // 更新播放列表
    playerStore.playlist = newPlaylist
    
    // 找到当前歌曲在新列表中的位置
    if (currentSongData) {
      const newIndex = newPlaylist.findIndex(song => song.id === currentSongData.id)
      if (newIndex !== -1) {
        playerStore.currentIndex = newIndex
      }
    }
  }
  
  playMode.value = newMode
  console.log('播放模式切换为:', playModeText.value)
}

// 切换喜欢状态
const toggleFavorite = async () => {
  if (!currentSong.value || !currentSong.value.id) return
  
  const song = currentSong.value
  const songData = {
    id: song.id,
    name: song.name,
    artists: song.artist ? [{ name: song.artist }] : [],
    album: {
      name: song.album || '',
      picUrl: song.cover || songCover.value || ''
    },
    duration: Math.round((song.duration || 0) * 1000)
  }
  
  if (isFavorited.value) {
    await playlistStore.removeFromFavorites(song.id)
  } else {
    const success = await playlistStore.addToFavorites(songData)
    if (success) {
      createFavoriteAnimation()
    }
  }
}

// 创建喜欢动画
const createFavoriteAnimation = () => {
  const button = document.querySelector('.favorite-btn')
  if (!button) return
  
  const rect = button.getBoundingClientRect()
  
  // 创建多个心形元素
  for (let i = 0; i < 5; i++) {
    const heart = document.createElement('div')
    heart.className = 'flying-heart'
    heart.innerHTML = '❤️'
    
    // 设置起始位置
    const startX = rect.left + rect.width / 2
    const startY = rect.top + rect.height / 2
    heart.style.left = startX + 'px'
    heart.style.top = startY + 'px'
    
    document.body.appendChild(heart)
    
    // 随机方向
    const angle = (Math.random() * 120 - 60) * Math.PI / 180
    const distance = 50 + Math.random() * 50
    const deltaX = Math.cos(angle) * distance
    const deltaY = -Math.abs(Math.sin(angle)) * distance - 30
    
    // 延迟启动动画
    setTimeout(() => {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          heart.style.transform = `translate(${deltaX}px, ${deltaY}px) scale(1.5) rotate(${Math.random() * 360}deg)`
          heart.style.opacity = '0'
        })
      })
    }, i * 50)
    
    // 动画结束后移除元素
    setTimeout(() => {
      heart.remove()
    }, 800 + i * 50)
  }
}

// 显示加入歌单对话框
const showAddToPlaylistDialog = (event) => {
  if (!currentSong.value) return
  
  // 阻止事件冒泡
  if (event) {
    event.stopPropagation()
  }
  
  console.log('点击加入歌单按钮', currentSong.value)
  
  songToAdd.value = {
    id: currentSong.value.id,
    name: currentSong.value.name,
    artists: currentSong.value.artist ? [{ name: currentSong.value.artist }] : [],
    album: {
      name: currentSong.value.album || '',
      picUrl: currentSong.value.cover || songCover.value || ''
    },
    duration: Math.round((currentSong.value.duration || 0) * 1000)
  }
  
  showAddDialog.value = true
  console.log('showAddDialog 设置为 true', showAddDialog.value)
}

const handleAddDialogClose = () => {
  showAddDialog.value = false
  songToAdd.value = null
}

const toggleMoreMenu = () => {
  showMoreMenu.value = !showMoreMenu.value
}

const handleAddToPlaylist = (event) => {
  showMoreMenu.value = false
  showAddToPlaylistDialog(event)
}

const handleGoToLyrics = () => {
  showMoreMenu.value = false
  goToLyrics()
}

const toggleFullscreenPlayer = () => {
  router.push('/player')
}
</script>

<style scoped>
.player-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  color: white;
  background: rgba(0, 0, 0, 0.7);
  padding: 15px 20px;
  border-radius: 8px;
}

.player-info {
  flex: 0 0 200px;
  width: 200px;
